package com.stocksense.inventory.stock;
import com.stocksense.ledger.*; import com.stocksense.product.*; import com.stocksense.warehouse.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service @RequiredArgsConstructor public class StockService { private final StockBalanceRepository balances; private final StockMovementRepository movements; private final ProductRepository products; private final LocationRepository locations; private StockBalance getLocked(Long p,Long l){return balances.lock(p,l).orElseGet(()->{StockBalance b=new StockBalance();b.setProduct(products.findById(p).orElseThrow());b.setLocation(locations.findById(l).orElseThrow());b.setQuantityOnHand(BigDecimal.ZERO);return balances.saveAndFlush(b);});} private void moveRecord(Product p,MovementType t,Location src,Location dst,BigDecimal q,String ref,String by){StockMovement m=new StockMovement();m.setMovementNumber("MOV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());m.setProduct(p);m.setType(t);m.setSourceLocation(src);m.setDestinationLocation(dst);m.setQuantity(q);m.setReferenceType(ref);m.setReferenceId(UUID.randomUUID().toString());m.setPerformedBy(by);movements.save(m);} private void validQty(BigDecimal q){if(q==null||q.signum()<=0)throw new IllegalArgumentException("Quantity must be greater than zero");}
@Transactional public void receive(Long p,Long loc,BigDecimal q,String by){validQty(q);StockBalance b=getLocked(p,loc);b.setQuantityOnHand(b.getQuantityOnHand().add(q));balances.save(b);moveRecord(b.getProduct(),MovementType.RECEIPT,null,b.getLocation(),q,"RECEIPT",by);} @Transactional public void deliver(Long p,Long loc,BigDecimal q,String by){validQty(q);StockBalance b=getLocked(p,loc);if(b.getQuantityOnHand().compareTo(q)<0)throw new IllegalStateException("Insufficient stock. Available: "+b.getQuantityOnHand());b.setQuantityOnHand(b.getQuantityOnHand().subtract(q));balances.save(b);moveRecord(b.getProduct(),MovementType.DELIVERY,b.getLocation(),null,q,"DELIVERY",by);} @Transactional public void transfer(Long p,Long src,Long dst,BigDecimal q,String by){validQty(q);if(src.equals(dst))throw new IllegalArgumentException("Source and destination must be different");StockBalance s=getLocked(p,src);if(s.getQuantityOnHand().compareTo(q)<0)throw new IllegalStateException("Insufficient stock. Available: "+s.getQuantityOnHand());StockBalance d=getLocked(p,dst);s.setQuantityOnHand(s.getQuantityOnHand().subtract(q));d.setQuantityOnHand(d.getQuantityOnHand().add(q));balances.save(s);balances.save(d);moveRecord(s.getProduct(),MovementType.TRANSFER_OUT,s.getLocation(),d.getLocation(),q,"TRANSFER",by);moveRecord(s.getProduct(),MovementType.TRANSFER_IN,s.getLocation(),d.getLocation(),q,"TRANSFER",by);} @Transactional public void adjust(Long p,Long loc,BigDecimal counted,String by){if(counted==null||counted.signum()<0)throw new IllegalArgumentException("Counted quantity cannot be negative");StockBalance b=getLocked(p,loc);BigDecimal diff=counted.subtract(b.getQuantityOnHand());if(diff.signum()==0)return;b.setQuantityOnHand(counted);balances.save(b);moveRecord(b.getProduct(),diff.signum()>0?MovementType.ADJUSTMENT_IN:MovementType.ADJUSTMENT_OUT,b.getLocation(),b.getLocation(),diff.abs(),"ADJUSTMENT",by);} public List<StockBalance> all(){return balances.findAll();} }
